import java.util.Scanner;

public class ProblemE {

	static final long MOD = 998244353;

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		long m = sc.nextLong();
		long n = sc.nextLong();
		long l = sc.nextLong();
		long r = sc.nextLong();
		sc.close();

		long total = m * n;
		long length = r - l + 1;

		long result = fastPower(length, total);
		if (total % 2 != 0) {
			System.out.println(result);
		} else {
			if (length % 2 == 0)
				System.out.println((result * modInverse(2, MOD)) % MOD);
			else
				System.out.println(((result + 1) % MOD * modInverse(2, MOD)) % MOD);
		}
	}

	public static long fastPower(long base, long exp) {
		long res = 1;
		long mod = MOD;
		while (exp > 0) {
			if ((exp & 1) == 1) {
				res = (res * base) % mod;
			}
			base = (base * base) % mod;
			exp >>= 1;
		}
		return res;
	}

	public static long modInverse(long a, long m) {
		return fastPower(a, m - 2);
	}
}
